parameters.jsCode:
// Get user's question from webhook
const webhookNode = $('1. Set Mock Input').first();
const webhookBody = webhookNode.json.body;

const userQuestion = webhookBody?.question;
const userLanguage = webhookBody?.language || 'English';

// Get all logs from Google Sheets (previous node)
const allLogs = $input.all();

// Validate input
if (!userQuestion) {
    return [{
        json: {
            cached: false,
            needsAI: true,
            error: "No question provided",
            question: "",
            language: userLanguage
        }
    }];
}

// **NEW: Handle empty Google Sheets response**
if (!allLogs || allLogs.length === 0) {
    return [{
        json: {
            question: userQuestion,
            cached: false,
            needsAI: true,
            similarQuestions: [],
            contextForAI: '',
            language: userLanguage,
            totalSimilarFound: 0,
            message: "No cached data found, proceeding with AI",
            // Pass through metadata
            latitude: webhookBody?.latitude,
            longitude: webhookBody?.longitude,
            deviceType: webhookBody?.deviceType,
            browser: webhookBody?.browser,
            queryType: webhookBody?.queryType,
            mobNo: webhookBody?.mobNo
        }
    }];
}

// Normalize text for comparison
function normalizeText(text) {
    if (!text) return '';
    return text.toLowerCase()
        .trim()
        .replace(/[^\w\s\u0900-\u097F]/g, '') // Keep Hindi characters
        .replace(/\s+/g, ' ');
}

// Calculate similarity between two strings
function calculateSimilarity(str1, str2) {
    const words1 = str1.split(' ').filter(w => w.length > 2);
    const words2 = str2.split(' ').filter(w => w.length > 2);

    if (words1.length === 0 || words2.length === 0) return 0;

    // Count matching words
    const matchingWords = words1.filter(word => words2.includes(word));

    // Calculate similarity score
    const similarity = matchingWords.length / Math.max(words1.length, words2.length);
    return similarity;
}

const normalizedUserQuestion = normalizeText(userQuestion);

// Search through logs for similar questions
const matches = [];

for (const log of allLogs) {
    const logData = log.json;

    // Skip if no question or answer
    if (!logData.question || !logData.answer) continue;

    // Skip if language doesn't match (optional)
    if (logData.language && userLanguage && logData.language !== userLanguage) continue;

    const normalizedLogQuestion = normalizeText(logData.question);
    const similarity = calculateSimilarity(normalizedUserQuestion, normalizedLogQuestion);

    // Only consider matches > 50% similar
    if (similarity > 0.5) {
        matches.push({
            originalQuestion: logData.question,
            question: normalizedLogQuestion,
            answer: logData.answer,
            response: logData.answer,
            language: logData.language || 'English',
            similarity: similarity,
            timestamp: logData.Timestamp,
            response_id: logData.response_id  // ← ADD THIS LINE
        });
    }
}

// Sort by similarity (highest first)
matches.sort((a, b) => b.similarity - a.similarity);

// Check for very high match (>85% = exact/near-exact match)
const exactMatch = matches.find(m => m.similarity > 0.85);

if (exactMatch) {
    // Return cached response immediately
    return [{
        json: {
            response: exactMatch.answer,
            source: 'cache',
            cached: true,
            similarity: exactMatch.similarity,
            question: userQuestion,
            language: exactMatch.language,
            success: true,
            matchedQuestion: exactMatch.originalQuestion,
            totalMatches: matches.length,
            // Pass through metadata
            latitude: webhookBody?.latitude,
            longitude: webhookBody?.longitude,
            deviceType: webhookBody?.deviceType,
            browser: webhookBody?.browser,
            queryType: webhookBody?.queryType,
            response_id: exactMatch.response_id,
            mobNo: webhookBody?.mobNo
        }
    }];
}

// No exact match - prepare context for AI
const topMatches = matches.slice(0, 5); // Top 5 similar questions

let contextForAI = '';
if (topMatches.length > 0) {
    if (userLanguage === 'Hindi') {
        contextForAI = 'पिछले समान प्रश्न और उत्तर:\n\n';
    } else {
        contextForAI = 'Previous similar questions and answers:\n\n';
    }

    topMatches.forEach((match, index) => {
        contextForAI += `${index + 1}. Q: ${match.originalQuestion}\n`;
        contextForAI += `   A: ${match.answer}\n\n`;
    });
    contextForAI += '---\n\n';
}

return [{
    json: {
        question: userQuestion,
        cached: false,
        needsAI: true,
        similarQuestions: topMatches,
        contextForAI: contextForAI,
        language: userLanguage,
        totalSimilarFound: topMatches.length,
        // Pass through metadata
        latitude: webhookBody?.latitude,
        longitude: webhookBody?.longitude,
        deviceType: webhookBody?.deviceType,
        browser: webhookBody?.browser,
        queryType: webhookBody?.queryType,
        mobNo: webhookBody?.mobNo
    }
}];

// Simplified Extract Question & Language
const items = $input.all();

// Try to get from first item directly (most common case)
let question = $input.first().json.question || $input.first().json.queryQuestion || '';
let language = $input.first().json.language || 'English';
let deviceType = $input.first().json.deviceType || 'NA';
let browser = $input.first().json.browser || 'NA';
let latitude = $input.first().json.latitude || 'NA';
let longitude = $input.first().json.longitude || 'NA';

console.log('Direct access - Question:', question);

// If not found, search through all items
if (!question) {
    for (const item of items) {
        if (item.json.question) {
            question = item.json.question;
            language = item.json.language || 'English';
            deviceType = item.json.deviceType || 'NA';
            browser = item.json.browser || 'NA';
            latitude = item.json.latitude || 'NA';
            longitude = item.json.longitude || 'NA';
            console.log('Found in items array');
            break;
        }

        // Check body (webhook)
        if (item.json.body?.question) {
            question = item.json.body.question;
            language = item.json.body.language || 'English';
            deviceType = item.json.body.deviceType || 'NA';
            browser = item.json.body.browser || 'NA';
            latitude = item.json.body.latitude || 'NA';
            longitude = item.json.body.longitude || 'NA';
            console.log('Found in body');
            break;
        }
    }
}

return [{
    json: {
        question: question || 'Error: No question found',
        language: language,
        deviceType: deviceType,
        browser: browser,
        latitude: latitude,
        longitude: longitude
    }
}];

// ============================================
// VERIFIED CODE v9.6 - GENERIC DISTRICT PROMPT BUILDER
// Fixed: Clean API Payload for Groq
// ============================================

const inputData = $input.first().json;
const rawText = inputData.text || inputData.data || '';

// Safely pull config from earlier node because HTML Extract wipes it
let config = {};
try {
    config = $('Apply District Config').first().json.config;
} catch (e) {
    console.log("Could not fetch config from Apply District Config node");
}

// 1. DYNAMIC DISTRICT VARIABLES
const districtName = config?.meta?.districtName || 'the district';
const state = config?.meta?.state || 'India';

// 2. DYNAMIC URLS
const officialLink = config?.urls?.districtGovt || '';

// 3. CONTENT PREPARATION
let question = inputData.message || inputData.query || '';
let language = inputData.language || 'en';
let isTourism = inputData.isTourism || false;

// If HTML Extract wiped these, pull from earlier node
if (!question) {
    try { question = $('Sanitize Query').first().json.message || ''; } catch (e) {}
}
if (!language) {
    try { language = $('Sanitize Query').first().json.language || 'en'; } catch (e) {}
}

const lowerMessage = question.toLowerCase();

// 4. BUILD SYSTEM PROMPT
let systemPrompt = `You are the official district information assistant for ${districtName}, ${state}.`;

systemPrompt += `\n\n**STRICT INSTRUCTIONS:**
1. You must extract answers ONLY from the provided scraped context. Do NOT use your general training data.
2. If the requested information (e.g., MP, MLA, DC) is NOT explicitly mentioned in the scraped text, do NOT provide generic advice, do NOT suggest searching elsewhere, and do NOT guess URLs.
3. If information is missing, reply EXACTLY with: "The requested information is currently not listed on the official district website's directory."
4. NEVER invent URLs like 'districts.nic.in'. Use ONLY provided official links.
5. DO NOT mention Haryana unless the district is in Haryana.`;

if (lowerMessage.match(/hotel|where to stay|accommodation|rest house|dharamshala/i) && isTourism) {
    systemPrompt += `\n\nACCOMMODATION QUERY:
    - Prioritize Government Facilities: State Tourist Complexes, Yatri Niwas, and Government Rest Houses.`;
}

systemPrompt += `\n\nLANGUAGE: ${language === 'hi' ? 'NATURAL HINDI' : 'Clear English'}`;

// 5. THE URL FIX
// ONLY append the official link if we actually successfully retrieved it from config
if (officialLink) {
    systemPrompt += '\n\n═══════════════════════════════════════════\nFORMATTING:\n1. Headers: **bold**\n2. Lists: • bullets\n3. Ending: Provide "---" followed by the link: ' + officialLink;
} else {
    systemPrompt += '\n\n═══════════════════════════════════════════\nFORMATTING:\n1. Headers: **bold**\n2. Lists: • bullets\n3. Ending: Do NOT append any links.';
}

// 6. CLEAN GROQ PAYLOAD
return [{
    json: {
        model: 'openai/gpt-oss-120b',
        temperature: 0.2,
        messages: [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: 'User Question: ' + question + '\n\nContext: ' + rawText.substring(0, 10000) }
        ]
        // Removed config, message, and language from here so Groq does not crash!
    }
}];

const content = $input.first().json.choices[0].message.content;

// Remove HTML from URLs

const cleanedContent = content.replace(/https?:\/\/[^\s<>"']+(<br>|<[^>]+>)/gi, (match, htmlTag) => {

  return match.replace(htmlTag, '');

});



return [{

  json: {

    response: cleanedContent

  }

}];

const data = $input.first().json;
const config = data.config || {};

console.log('=== Final Link Routing ===');
console.log('District:', config?.meta?.districtName || 'Unknown');

const getGovtPage = (pageName) => {
    const fallbackDomain = (config?.urls?.districtGovt || 'kurukshetra.gov.in').replace(/^https?:\/\//, '');
    return config?.govtPages?.[pageName] || `https://${fallbackDomain}`;
};

if (data.isPrivateBusiness) {
    return [{ json: { ...data, noResults: true, isPrivateBusiness: true, isTourism: false } }];
}

// ============================================
// PERSON QUERIES - THE INTENT SPLITTER
// ============================================
if (data.queryCategory === 'person') {
    let msg = (data.message || '').toLowerCase();

    // --- THE FIX: Strip the injected generic keywords to reveal the real question ---
    if (msg.includes('profile contact email')) {
        msg = msg.split('profile contact email')[0];
    }

    const hasAdmin = /\b(dc|dm|deputy commissioner|district magistrate|collector|sp|ias|ips|officer)\b/i.test(msg);
    const hasPolitical = /\b(mla|mp|minister|political|representative|parliament|assembly|politician)\b/i.test(msg);

    const isPolitical = hasPolitical && !hasAdmin;

    // --- PATH A: POLITICAL QUERIES (MLAs, MPs, Ministers) ---
    if (isPolitical) {
        console.log('✓ Political query detected:', msg);
        const politicalLink = config?.govtPages?.politicalSetup;

        if (politicalLink && politicalLink.trim() !== "") {
            return [{ json: { ...data, link: politicalLink, noResults: false, queryCategory: 'person' } }];
        }

        if (data.organic_results && data.organic_results.length > 0) {
            const bestPolLink = data.organic_results.find(res => 
                res.link.match(/\/(elected-representatives|political-setup|mla|mp|representatives)\/?$/i)
            ) || data.organic_results[0];
            return [{ json: { ...data, link: bestPolLink.link, noResults: false, queryCategory: 'person' } }];
        }

        const fallbackDir = config?.govtPages?.directory || config?.govtPages?.whoswho || getGovtPage('directory');
        return [{ json: { ...data, link: fallbackDir, noResults: false, queryCategory: 'person' } }];

    // --- PATH B: ADMINISTRATIVE QUERIES (DC, DM, SP) ---
    } else {
        console.log('✓ Admin query detected:', msg);
        const configUrl = config?.govtPages?.whoswho || '';
        let finalLink = '';

        if (data.organic_results && data.organic_results.length > 0) {
            // 1. Exact Config Match
            let matchedResult = data.organic_results.find(res => res.link === configUrl);

            // 2. Fuzzy Config Match (Ignore hyphens)
            if (!matchedResult && configUrl) {
                const cleanConfig = configUrl.toLowerCase().replace(/-/g, '').replace(/\/$/, '');
                matchedResult = data.organic_results.find(res => 
                    res.link.toLowerCase().replace(/-/g, '').replace(/\/$/, '') === cleanConfig
                );
            }

            if (matchedResult) {
                finalLink = matchedResult.link;
            } else {
                // 3. Safe Search Match
                const validSearchLink = data.organic_results.find(res => 
                    res.link.match(/\/(whos-who|whoswho|directory)\/?$/i) && 
                    !res.link.includes('home11')
                );
                if (validSearchLink) finalLink = validSearchLink.link;
            }
        }

        // 4. Force JSON if Search fails
        if (!finalLink && configUrl) {
            finalLink = configUrl;
        }

        // 5. Absolute Last Resort
        if (!finalLink) finalLink = getGovtPage('directory');

        return [{ json: { ...data, link: finalLink, noResults: false, queryCategory: 'person' } }];
    }
}

// ============================================
// VILLAGE ADMIN / ADMIN STRUCTURE / DEMOGRAPHIC
// ============================================
if (data.queryCategory === 'village_admin') {
    return [{ json: { ...data, link: getGovtPage('directory'), noResults: false } }];
}
if (data.queryCategory === 'admin_structure') {
    return [{ json: { ...data, link: getGovtPage('adminSetup'), noResults: false } }];
}
if (['demographic', 'village_demographic', 'tehsil_demographic'].includes(data.queryCategory)) {
    return [{ json: { ...data, link: getGovtPage('knowAbout'), noResults: false } }];
}

// ============================================
// TOURISM & REGULAR FALLBACK
// ============================================
if (data.isTourism && (data.primaryLink || data.secondaryLink)) {
    return [{ json: { ...data, link: data.primaryLink || data.secondaryLink, noResults: false } }];
}

if (!data.organic_results || data.organic_results.length === 0) {
    return [{ json: { ...data, noResults: true } }];
} else {
    return [{ json: { ...data, link: data.organic_results[0].link, noResults: false } }];
}

