parameters.jsCode:
// ============================================
// MERGE TOURISM LINKS - GENERIC VERSION
// ============================================

const checkTourismData = $('Check_Tourism_Query').first().json;
const config = checkTourismData.config || {};
const message = checkTourismData.message || '';
const language = checkTourismData.language || 'en';
const isBroad = checkTourismData.isBroadTourism || false;
const perspective = checkTourismData.perspective || 'general';

const districtKey = config?.meta?.districtKey || 'kurukshetra';

console.log('=== Merge Tourism Links ===');
console.log('District:', districtKey);
console.log('Message:', message);
console.log('Is Broad:', isBroad);
console.log('Perspective:', perspective);

// Assuming node names remained the same. If you renamed them to Search_Tourism1 etc., update here.
let searchRes1 = { organic_results: [] }, searchRes2 = { organic_results: [] }, searchRes3 = { organic_results: [] };
try { searchRes1 = $('Search_KKRTour').first().json; } catch(e){}
try { searchRes2 = $('Search_Govt_Tourism').first().json; } catch(e){}
try { searchRes3 = $('Search_Haryana_Tourism').first().json; } catch(e){}

// Fallback URLs from Config
const broadPrimary = config?.tourismSites?.broadQueryPrimary || 'https://haryanatourism.gov.in';
const broadSecondary = config?.tourismSites?.broadQuerySecondary || config?.govtPages?.attractions || 'https://haryana.gov.in';
const genPrimary = config?.tourismSites?.generalListPrimary || broadPrimary;
const genSecondary = config?.tourismSites?.generalListSecondary || broadSecondary;

let primaryLink = '';
let secondaryLink = '';
let tertiaryLink = '';

// ============================================
// DETECT GENERAL LIST QUERIES
// ============================================
const generalQueryKeywords = [
    'tourist places', 'tourist spots', 'places to visit',
    'attractions', 'sightseeing', 'what to see', 'tourism',
    'main places', 'important places', 'famous places',
    'top places', 'best places', 'all places',
    `${districtKey} mein`, `${districtKey} ke`, `${districtKey} ki`,
    'पर्यटन स्थल', 'दर्शनीय स्थल', 'घूमने की जगह',
    'मुख्य स्थान', 'प्रमुख स्थान'
];

const lowerMessage = message.toLowerCase();

// Get specific sites from config to ensure we don't treat specific queries as general
const specificSites = config?.keywords?.tourismSpecifics || [];
const mentionsSpecificSite = specificSites.some(site => lowerMessage.includes(site.toLowerCase()));

const isGeneralListQuery = generalQueryKeywords.some(kw => lowerMessage.includes(kw)) && !mentionsSpecificSite;

console.log('isGeneralListQuery:', isGeneralListQuery);

if (isGeneralListQuery) {
    console.log('General tourism query - returning overview links');
    return [{
        json: {
            ...checkTourismData,
            isTourism: true,
            is48Kos: false,
            isGeneralQuery: true,
            primaryLink: genPrimary,
            secondaryLink: genSecondary,
            tertiaryLink: null,
            matchedSite: null
        }
    }];
}

// PERSPECTIVE FALLBACKS (Dynamic from config)
const PERSPECTIVE_URLS = config?.perspectiveFallbackUrls || {
    general: { primary: broadPrimary, secondary: broadSecondary }
};

// ============================================
// BROAD QUERY CHECK
// ============================================
if (isBroad) {
    console.log('✓ BROAD query detected');
    primaryLink = broadPrimary;
    secondaryLink = broadSecondary;

} else {
    // ============================================
    // DYNAMIC KNOWN_SITES MAPPING
    // ============================================
    const KNOWN_SITES = config?.knownSites || {};

    // SMART MATCHING LOGIC
    function normalizeForMatching(text) {
        return text.toLowerCase()
            .replace(/[_\-\s]+/g, ' ')
            .replace(/[^a-z0-9\s\u0900-\u097F]/g, '') 
            .trim();
    }

    function wordsMatch(word1, word2) {
        if (word1 === word2) return true;
        if (word1.length >= 4 && word2.length >= 4 && (word1.includes(word2) || word2.includes(word1))) return true;
        if (word1.length >= 5 && word2.length >= 5 && word1.substring(0, 5) === word2.substring(0, 5)) return true;
        return false;
    }

    const normalizedMessage = normalizeForMatching(lowerMessage);
    let siteData = null;
    let matchedSite = null;

    console.log('Normalized message:', normalizedMessage);

    // PASS 1: Exact substring match
    for (const [siteName, data] of Object.entries(KNOWN_SITES)) {
        if (lowerMessage.includes(siteName.toLowerCase())) {
            siteData = data;
            matchedSite = siteName;
            console.log(`→ Exact match: "${siteName}"`);
            break;
        }
    }

    // PASS 2: Normalized fuzzy match
    if (!siteData) {
        for (const [siteName, data] of Object.entries(KNOWN_SITES)) {
            const normalizedSiteName = normalizeForMatching(siteName);

            if (normalizedMessage.includes(normalizedSiteName)) {
                siteData = data;
                matchedSite = siteName;
                console.log(`→ Normalized match: "${siteName}"`);
                break;
            }

            const siteWords = normalizedSiteName.split(' ').filter(w => w.length > 0);
            const messageWords = normalizedMessage.split(' ').filter(w => w.length > 0);

            if (siteWords.length >= 2) {
                const matchCount = siteWords.filter(siteWord => messageWords.some(msgWord => wordsMatch(siteWord, msgWord))).length;
                const requiredMatches = siteWords.length > 2 ? siteWords.length - 1 : siteWords.length;

                if (matchCount >= requiredMatches) {
                    siteData = data;
                    matchedSite = siteName;
                    console.log(`→ Word match: "${siteName}" (${matchCount}/${siteWords.length} words)`);
                    break;
                }
            }
        }
    }

    // ============================================
    // GENERATE LINKS FROM MATCHED SITE
    // ============================================
    if (siteData) {

        // Handle New Config Object Format: { "type": "tourism", "url": "https://..." }
        if (typeof siteData === 'object') {

            // 48 KOS SPECIFIC ROUTING
            if (siteData.type === '48kos') {
                console.log('→ 48 Kos Tirtha detected');
                if (siteData.kkrId && config.tourismSites?.kkrTourListTemplate) {
                    primaryLink = config.tourismSites.kkrTourListTemplate.replace('{siteId}', siteData.kkrId);
                } else if (config.tourismSites?.['48kosTemplate'] && siteData.kosSite) {
                    primaryLink = config.tourismSites['48kosTemplate'].replace('{kosSite}', siteData.kosSite);
                }

                if (siteData.govSite) {
                    secondaryLink = `https://${config.urls.districtGovt}/${siteData.govSite}/`;
                } else {
                    secondaryLink = config.govtPages?.['48kosMain'] || broadSecondary;
                }

                if (config.tourismSites?.['48kosTemplate'] && siteData.kosSite) {
                    tertiaryLink = config.tourismSites['48kosTemplate'].replace('{kosSite}', siteData.kosSite);
                }
            } 
            // STANDARD CONFIG URL
            else if (siteData.url) {
                primaryLink = siteData.url;
                secondaryLink = broadSecondary;
            }
            // LEGACY KKRTOUR ID
            else if (siteData.id && config.tourismSites?.kkrTourListTemplate) {
                primaryLink = config.tourismSites.kkrTourListTemplate.replace('{siteId}', siteData.id);
                secondaryLink = broadSecondary;
            }
        } 
        // Fallbacks for Legacy String/Number configs
        else if (typeof siteData === 'string' && siteData.startsWith('http')) {
            primaryLink = siteData;
            secondaryLink = broadSecondary;
        } else if (typeof siteData === 'number' && config.tourismSites?.kkrTourListTemplate) {
            primaryLink = config.tourismSites.kkrTourListTemplate.replace('{siteId}', siteData);
            secondaryLink = broadSecondary;
        }
    } else {
        // FALLBACK TO SEARCH RESULTS
        if (searchRes1.organic_results && searchRes1.organic_results.length > 0) {
            primaryLink = searchRes1.organic_results[0].link.trim().split(/[\s<>]/)[0];
        } else if (searchRes2.organic_results && searchRes2.organic_results.length > 0) {
            primaryLink = searchRes2.organic_results[0].link.trim().split(/[\s<>]/)[0];
        } else if (searchRes3.organic_results && searchRes3.organic_results.length > 0) {
            primaryLink = searchRes3.organic_results[0].link.trim().split(/[\s<>]/)[0];
        } else {
            const fallback = PERSPECTIVE_URLS[perspective] || PERSPECTIVE_URLS['general'] || {};
            primaryLink = fallback.primary || broadPrimary;
            secondaryLink = fallback.secondary || broadSecondary;
        }
    }

    // GET SECONDARY IF NOT SET
    if (!secondaryLink) {
