    'पर्यटन', 'मंदिर', 'तीर्थ', 'दर्शनीय', 'स्थल', 'यक्ष',
    'संग्रहालय', 'पुरातात्विक', 'पवित्र', 'धार्मिक', 'घूमने', 'अनुभव', 'केंद्र'
];

// Dynamically pull the specific sites for the current district from JSON
// (Make sure your JSON's tourismSpecifics array includes the Hindi names too!)
const districtSpecificSites = config?.keywords?.tourismSpecifics || [];

// Combine universal keywords with district-specific ones
const allKeywords = [...generalTourismKeywords, ...districtSpecificSites];

const isTourism = allKeywords.some(kw => lowerMessage.includes(kw.toLowerCase()));

console.log('Is Tourism Query:', isTourism);

// ============================================
// 2. PRIVATE BUSINESS DETECTION (Universal)
// ============================================
// This logic remains exactly the same as your original, as it applies to any city
const privateBusinessKeywords = [
    'pizza', 'burger', 'chinese', 'italian', 'mexican', 'fast food',
    'cafe', 'coffee shop', 'bakery', 'sweet shop', 'confectionery',
