    '/gallery/', '/photo-gallery/', '/video-gallery/', '/images/',

    // Other irrelevant
    '/events-calendar/', '/feedback/', '/contact-form/',
    '/guest-book/', '/sitemap/', '/search/', '/login/'
];

// DYNAMIC Good URL patterns (priority scores)
const goodPatterns = [
    { pattern: `know-${districtKey}`, score: 10 },    // e.g., know-karnal, know-kurukshetra
    { pattern: `about-${districtKey}`, score: 10 },   // e.g., about-karnal, about-kurukshetra
    { pattern: 'about-district', score: 10 },
    { pattern: 'demographic', score: 9 },
    { pattern: 'census', score: 9 },
    { pattern: 'population', score: 8 },
    { pattern: 'administration', score: 8 },
    { pattern: 'services', score: 7 }
];

// Filter and score URLs
const validUrls = [];

for (const result of allResults) {
    const url = result.link || '';

    if (!url) continue;

    // Skip bad patterns
    const isBad = skipPatterns.some(pattern => 
        url.toLowerCase().includes(pattern)
    );

    if (isBad) {
        const matchedPattern = skipPatterns.find(p => url.toLowerCase().includes(p));
        console.log(`⏭️ Skipping bad URL: ${url}`);
        console.log(`   Reason: Contains pattern "${matchedPattern}"`);
        continue;
    }

    // Calculate priority score
    let score = 0;
    for (const good of goodPatterns) {
        if (url.toLowerCase().includes(good.pattern)) {
            score += good.score;
        }
    }

    // Prefer HTTPS
    if (url.startsWith('https://')) score += 1;

    // Prefer shorter URLs
    const pathDepth = url.split('/').length;
    if (pathDepth <= 5) score += 2;

    validUrls.push({
        ...result,
        link: url,
        priorityScore: score
    });
}

// Sort by priority
validUrls.sort((a, b) => b.priorityScore - a.priorityScore);

console.log(`✅ Filtered: ${validUrls.length} valid URLs (from ${allResults.length})`);

// ========================================
