if (data.is48Kos && data.tertiaryLink) {
    url = data.tertiaryLink;
    console.log('→ Heritage/Tertiary site detected:', url);
} else {
    console.log('→ Regular site:', url);
}

if (url && !url.startsWith('http')) {
    url = 'https://' + url;
    console.log('🔧 Auto-fixed URL protocol:', url);
}

console.log('=== Smart Scraper ===');
console.log('URL to scrape:', url);

if (!url || url.trim() === '') {
    return [{ json: { ...data, error: 'No URL to scrape', success: false } }];
}

console.log(`📡 Attempting to scrape: ${url}`);

// HELPER: Simple check to see if a string is mostly readable text instead of binary
function isReadableText(str) {
    if (str.length < 500) return false;
    // Check if it has a high ratio of standard ASCII/text characters
    const readableChars = str.match(/[a-zA-Z0-9\s<>{}="':;\.,\/\-]/g);
    if (!readableChars) return false;
    const ratio = readableChars.length / str.length;
    // If more than 70% of the document is standard characters, it's a webpage, not a JPEG.
    return ratio > 0.7;
}

try {
    const response = await this.helpers.httpRequest({
        method: 'GET',
        url: url,
        timeout: 15000,
        headers: {
            'Accept': 'text/html,application/xhtml+xml,application/xml',
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
        },
        returnFullResponse: false,
        skipSslCertificateValidation: true
    });

    if (response) {
        const html = String(response);
        console.log(`✅ SUCCESS: Downloaded ${html.length} bytes`);

        // Use the relaxed text-ratio check instead of strict tag checking
        if (isReadableText(html)) {
            return [{
                json: {
                    ...data,
                    data: html,
                    url: url,
                    success: true,
                    htmlLength: html.length
                }
            }];
        } else {
            console.log('⚠️ Response appears to be an image or binary file (failed text ratio)');
            throw new Error('Received binary/image data instead of webpage');
        }
    }

} catch (error) {
    console.log('Scraping failed:', error.message);

    let fallbackUrl = url;
    if (data.link && url !== data.link) {
        fallbackUrl = data.link;
        console.log('Falling back to primary link:', fallbackUrl);
    } else if (data.secondaryLink && url !== data.secondaryLink) {
        fallbackUrl = data.secondaryLink;
        console.log('Falling back to secondary link:', fallbackUrl);
    } else {
        return [{ json: { ...data, success: false, error: error.message, url: url } }];
    }

    try {
        const fallbackResponse = await this.helpers.httpRequest({
            method: 'GET',
            url: fallbackUrl,
            timeout: 15000,
            headers: {
                'Accept': 'text/html',
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'
            },
            returnFullResponse: false,
            skipSslCertificateValidation: true
        });

        if (fallbackResponse) {
            const html = String(fallbackResponse);

            if (isReadableText(html)) {
                console.log('Fallback SUCCESS:', html.length, 'chars');
                return [{
                    json: {
                        ...data,
                        data: html,
                        url: fallbackUrl,
                        success: true,
                        htmlLength: html.length,
                        usedFallback: true
                    }
                }];
            }
        }
    } catch (fallbackError) {
        console.log('Fallback also failed:', fallbackError.message);
    }

    return [{
        json: {
            ...data,
            success: false,
            error: error.message,
            url: url
        }
    }];
}

return [{
    json: {
        ...data,
        success: false,
        error: 'No response received',
        url: url
    }
}];

