// ============================================
// VERIFIED CODE v2.1 - MULTI-STATE QUERY ENHANCER
// Generic logic for DC/DM/Collector and boost keywords
// ============================================

const inputData = $input.first().json;
const query = inputData.message || inputData.question || '';
const language = inputData.language || 'en';
const config = inputData.config || {};

console.log('=== Smart Query Enhancer ===');
console.log('District:', config?.meta?.districtName || 'Unknown');

const lowerQuery = query.toLowerCase();
let enhancedQuery = query;
let category = 'general';
let boostKeywords = '';

// 1. REGIONAL STATE LOGIC
const state = config?.meta?.state || 'Haryana';
const isDMRegion = (state === 'Uttarakhand' || state === 'Uttar Pradesh');
const isCollectorRegion = (state === 'Rajasthan');

// ============================================
// PERSON QUERIES (GENERIC TERMINOLOGY MAPPING)[cite: 2]
// ============================================
const personKeywords = /who is|mla|mp|minister|deputy commissioner|dc|dm|sdm|sub divisional magistrate|sp|superintendent of police|adc|additional deputy|collector|tehsildar|sho|station house officer|विधायक|सांसद|मंत्री/i;

if (lowerQuery.match(personKeywords)) {
    const isPersonQuery = 
        lowerQuery.includes('who is') || 
        lowerQuery.includes('who\'s') ||
        lowerQuery.includes('current') ||
        lowerQuery.match(/\bmla\b/i) || 
        lowerQuery.match(/\bmp\b/i) ||
        lowerQuery.includes('minister') ||
        lowerQuery.includes('विधायक') ||
        lowerQuery.includes('सांसद') ||
        (lowerQuery.match(/\b(dc|dm|sdm|sp|adc|collector|tehsildar|sho)\b/) && 
         !lowerQuery.includes('office') && 
         !lowerQuery.includes('location'));

    if (isPersonQuery) {
        category = 'person';

        // MAPPING: Ensure search finds the right title for the right state
        let titleBoost = 'profile contact email phone designation';

        if (isDMRegion) {
            // Force DM keywords for Uttarakhand/UP even if user types DC[cite: 2]
            titleBoost += ' District Magistrate DM District Collector';
        } else if (isCollectorRegion) {
            titleBoost += ' District Collector Collector DM';
        } else {
            // Default for Haryana/Punjab[cite: 2]
            titleBoost += ' Deputy Commissioner DC Collector';
        }

        boostKeywords = `${titleBoost} MLA MP minister representative`;
        console.log(`→ Category: Person Query (${state} titles applied)`);
    }
}

// ============================================
// VILLAGE & ADMIN STRUCTURE (STAYS GENERIC)[cite: 2]
// ============================================
if (category === 'general') {
    if (lowerQuery.match(/sarpanch|panch|gram panchayat|village head|pradhan|mukhiya/i)) {
        boostKeywords = 'sarpanch panch list directory village panchayat pradhan';
        category = 'village_admin';
    } 
    else if (lowerQuery.match(/tehsil|sub division|sub-division|block|administrative division/i)) {
        boostKeywords = 'tehsil list sub-division administrative structure subdivision';
        category = 'admin_structure';
    }
    else if (lowerQuery.match(/sex ratio|population|literacy|census|demograph/i)) {
        boostKeywords = 'demography statistics census data know about';
        category = 'demographic';
    }
}

// ============================================
// BUILD FINAL ENHANCED QUERY[cite: 2]
// ============================================
if (boostKeywords) {
    enhancedQuery = `${query} ${boostKeywords}`;
}

return [{
    json: {
        ...inputData,
        message: enhancedQuery,           // Enhanced for SerpAPI search[cite: 2]
        originalQuery: query,
        enhancedQuery: enhancedQuery,
        queryCategory: category,
        boostKeywords: boostKeywords
    }
}];

// ============================================
// DEMOGRAPHIC DATA EXTRACTOR (SAFE & GENERIC)
// Forcefully extracts census data from scraped content
// ============================================

const inputData = $input.first().json;
// Check both 'text' and 'data' just in case of different previous nodes
const scrapedText = inputData.text || inputData.data || '';
const config = inputData.config || {};

// Safely get queryCategory with fallback
let queryCategory = inputData.queryCategory || 'general';
try {
    const enhancer = $('Smart_Query_Enhancer').first();
    if (enhancer && enhancer.json && enhancer.json.queryCategory) {
        queryCategory = enhancer.json.queryCategory;
    }
} catch (e) {
    console.log('Smart_Query_Enhancer not found, using fallback');
}

console.log('=== Demographic Data Extractor ===');
console.log('Query Category:', queryCategory);

let extractedData = {
    population: null,
    sexRatio: null,
    literacyRate: null,
    density: null,
    growthRate: null
};

// Only extract if this is a demographic query
// (Added tehsil/village demographic checks just to be safe)
if (queryCategory === 'demographic' || queryCategory === 'tehsil_demographic' || queryCategory === 'village_demographic') {
    console.log('Extracting demographic data...');

    // Extract Population
    const popMatch = scrapedText.match(/population of ([\d,]+)/i);
    if (popMatch) {
        extractedData.population = popMatch[1];
        console.log('✓ Found population from text:', extractedData.population);
    } else if (config?.meta?.population) {
        // ⚡ THE SUPER FALLBACK: Pull from our GitHub JSON if Regex fails!
        extractedData.population = config.meta.population;
        console.log('✓ Used fallback population from config:', extractedData.population);
    }

    // Extract Sex Ratio (multiple patterns)
    const sexRatioPatterns = [
        /sex ratio of (\d+) females/i,
        /(\d+) females for every 1000 males/i,
        /sex ratio[^\d]*(\d+)/i
    ];

    for (const pattern of sexRatioPatterns) {
        const match = scrapedText.match(pattern);
        if (match) {
            extractedData.sexRatio = match[1];
            console.log('✓ Found sex ratio:', extractedData.sexRatio);
            break;
        }
    }

    // Extract Literacy Rate
    const literacyMatch = scrapedText.match(/literacy rate of ([\d.]+)%/i);
    if (literacyMatch) {
        extractedData.literacyRate = literacyMatch[1];
        console.log('✓ Found literacy rate:', extractedData.literacyRate);
    }

    // Extract Density
    const densityMatch = scrapedText.match(/density of (\d+) inhabitants/i);
    if (densityMatch) {
        extractedData.density = densityMatch[1];
        console.log('✓ Found density:', extractedData.density);
    }

    // Extract Growth Rate
    const growthMatch = scrapedText.match(/growth rate[^\d]*([\d.]+)%/i);
    if (growthMatch) {
        extractedData.growthRate = growthMatch[1];
        console.log('✓ Found growth rate:', extractedData.growthRate);
    }
}

console.log('=== Extracted Data ===');
console.log(JSON.stringify(extractedData, null, 2));
console.log('======================');

// Pass through all data plus extracted demographics
return [{
    json: {
        ...inputData, // Safe preservation of config and previous data
        extractedDemographics: extractedData,
        queryCategory: queryCategory
    }
}];

