    responseType = 'not_available';
} 
else if (respLower.includes('priharyana.nic.in') || 
         respLower.includes('census2011.co.in') ||
         respLower.includes('ceoharyana.gov.in') ||
         respLower.includes('jamabandi.nic.in')) {
    responseType = 'external_link';
} 
// DYNAMIC CHECK: Does the source link contain the active district's gov domain?
else if (sourceLink && sourceLink.includes(govBase)) {
    responseType = 'website_scraped';
}

console.log('Response Type:', responseType);

// ============================================
// DETERMINE CACHE FLAG
// ============================================

let cacheFlag = 'REVIEW';
if (responseType === 'private_business' || 
    responseType === 'not_available' || 
    responseType === 'ai_fallback') {
    cacheFlag = 'NO';
} else if (responseType === 'website_scraped') {
    cacheFlag = 'YES';
}

console.log('Cache Flag:', cacheFlag);

// ============================================
// DETERMINE FLAG REASON
// ============================================

let flagReason = 'unknown';
if (responseType === 'private_business') {
    flagReason = 'private_business';
} else if (responseType === 'not_available' || responseType === 'ai_fallback') {
    flagReason = 'no_website_data';
} else if (responseType === 'external_link') {
    flagReason = 'external_portal';
} else if (responseType === 'website_scraped') {
    flagReason = 'government_source';
}

console.log('Flag Reason:', flagReason);

// ============================================
// RETURN ALL DATA WITH NEW FIELDS
// ============================================

return [{
    json: {
        ...input, // Preserve all incoming data, including config

        Timestamp: new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }),
        question: question,
        response: aiResponse,
        language: language,
        deviceType: deviceType,
        source: sourceData,
        response_id: responseId,

        // NEW ANALYTICS FIELDS
        Response_Type: responseType,
        Source_URL: sourceLink,
        Cache_Flag: cacheFlag,
        Flag_Reason: flagReason,
        Query_Category: queryCategory
    }
}];

// ============================================
// APPLY DISTRICT CONFIG (FOOLPROOF VERSION)
// ============================================

// 1. Get the data from the Sanitize node
let inputJson = {};
try {
    inputJson = $('Sanitize Query').first().json;
} catch(e) {
    inputJson = $('1. Set Mock Input').first().json || {};
}

// 2. Extract EXACTLY what we need. 
// We use the cleaned text at the top level. We ignore the dirty webhook body!
const cleanMessage = inputJson.message || '';
const cleanQuestion = inputJson.question || '';
const lang = inputJson.language || (inputJson.body ? inputJson.body.language : 'en');
const city = inputJson.city || (inputJson.body ? inputJson.body.city : 'kurukshetra');

// 3. Get the full config fetched from GitHub
const allConfigs = $input.first().json;
const districtsData = allConfigs.districts ? allConfigs.districts : allConfigs;

// 4. Determine the district being queried
const districtKey = city.toLowerCase();

// 5. Extract the specific district's configuration
const activeConfig = districtsData[districtKey];

if (!activeConfig) {
    throw new Error(`Configuration not found for district: ${districtKey}`);
}

// 6. Output a perfectly flat, clean JSON object for the rest of the workflow
return [{
    json: {
        question: cleanQuestion,
        message: cleanMessage,
        query: cleanMessage, // Pass 'query' too just to be safe
        language: lang,
        city: city,
        config: activeConfig
    }
}];

// ============================================
// EMOJI & SYMBOL SANITIZER (FIXED FOR WEBHOOK)
// ============================================
const data = $input.first().json;

// 1. Locate the actual payload (Webhooks put it inside 'body')
const payload = data.body || data;

// 2. Extract the text securely (ignoring empty objects)
let rawText = payload.message || payload.question || '';
if (typeof rawText === 'object') {
    rawText = ''; // Prevent [object Object] errors
}

let text = String(rawText);

// 3. Advanced Regex: Removes emojis but KEEPS English, Hindi, and normal punctuation
const cleanText = text
    .replace(/([\u2700-\u27BF]|[\uE000-\uF8FF]|\uD83C[\uDC00-\uDFFF]|\uD83D[\uDC00-\uDFFF]|[\u2011-\u26FF]|\uD83E[\uDD10-\uDDFF])/g, '')
    .replace(/\s+/g, ' ') // Remove extra double spaces left behind by deleted emojis
    .trim();

console.log('Original:', text);
console.log('Cleaned:', cleanText);

// 4. Return data, promoting variables to the top level so the next nodes can easily read them
return [{
    json: {
        ...data,
        ...payload, // Brings 'city', 'language', etc., to the top level
        message: cleanText,
        question: cleanText,
        query: cleanText, // Overwrites the empty webhook query object
        original_message_with_emoji: text
    }
}];
